import sys

def max_sub_array_sum_repeated(arr, n, k):
    max_so_far = -sys.maxsize
    max_ending_here = 0
    total_sum = sum(arr)
    if total_sum < 0:
        return max_subarray(arr)
    else:
        return max_subarray(arr) + (k - 1) * total_sum

def max_subarray(arr):
    max_so_far = -sys.maxsize
    max_ending_here = 0
    for x in arr:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far
